## 3) Priority-1: Idempotency (mandatory) — **Apex implementation**

### 3.1 Idempotency service (atomic create-or-return)

```apex
public with sharing class IdempotencyService {

    public class IdemResult {
        public Boolean isDuplicate;
        public String responseJson;
        public Orch_Idempotency__c record;
    }

    // requestBodyJson is what you are about to execute; stored hash prevents "same key, different request"
    public static IdemResult begin(String scope, String idemKey, String requestBodyJson, Integer ttlMinutes) {
        if (String.isBlank(idemKey)) {
            throw new AuraHandledException('Missing Idempotency Key (required).');
        }
        String hash = CryptoUtil.sha256Hex(requestBodyJson);

        // Try read first (fast path)
        List<Orch_Idempotency__c> existing = [
            SELECT Id, IdempotencyKey__c, Scope__c, RequestHash__c, Status__c, ResponseJson__c, ExpiresAt__c
            FROM Orch_Idempotency__c
            WHERE IdempotencyKey__c = :idemKey AND Scope__c = :scope
            LIMIT 1
        ];
        if (!existing.isEmpty()) {
            Orch_Idempotency__c rec = existing[0];

            // Guard: same key cannot be reused for different request
            if (rec.RequestHash__c != hash) {
                throw new AuraHandledException('Idempotency key reuse with different request payload is not allowed.');
            }
            IdemResult dup = new IdemResult();
            dup.isDuplicate = true;
            dup.responseJson = rec.ResponseJson__c;
            dup.record = rec;
            return dup;
        }

        // Slow path: attempt insert; if racing, unique constraint will throw and we then re-read
        Orch_Idempotency__c toInsert = new Orch_Idempotency__c();
        toInsert.Scope__c = scope;
        toInsert.IdempotencyKey__c = idemKey;
        toInsert.RequestHash__c = hash;
        toInsert.Status__c = 'InProgress';
        toInsert.ExpiresAt__c = System.now().addMinutes(ttlMinutes);

        try {
            insert toInsert;
            IdemResult fresh = new IdemResult();
            fresh.isDuplicate = false;
            fresh.record = toInsert;
            return fresh;
        } catch (DmlException e) {
            // race: re-read and return
            Orch_Idempotency__c rec = [
                SELECT Id, RequestHash__c, Status__c, ResponseJson__c
                FROM Orch_Idempotency__c
                WHERE IdempotencyKey__c = :idemKey AND Scope__c = :scope
                LIMIT 1
            ];
            if (rec.RequestHash__c != hash) {
                throw new AuraHandledException('Idempotency key collision with different request payload.');
            }
            IdemResult dup = new IdemResult();
            dup.isDuplicate = true;
            dup.responseJson = rec.ResponseJson__c;
            dup.record = rec;
            return dup;
        }
    }

    public static void succeed(Id recordId, String responseJson) {
        Orch_Idempotency__c rec = new Orch_Idempotency__c(Id = recordId);
        rec.Status__c = 'Succeeded';
        rec.ResponseJson__c = responseJson;
        update rec;
    }

    public static void fail(Id recordId, String responseJson) {
        Orch_Idempotency__c rec = new Orch_Idempotency__c(Id = recordId);
        rec.Status__c = 'Failed';
        rec.ResponseJson__c = responseJson;
        update rec;
    }
}

public class CryptoUtil {
    public static String sha256Hex(String body) {
        Blob b = Blob.valueOf(body == null ? '' : body);
        Blob hash = Crypto.generateDigest('SHA-256', b);
        return EncodingUtil.convertToHex(hash).toLowerCase();
    }
}
```

