## 5) Priority-1: Retry policy per step (mandatory)

### 5.1 Orchestrator runner (Queueable) with per-step retry

```apex
public with sharing class OrchStepRunner implements Queueable, Database.AllowsCallouts {

    private Id executionId;
    private String stepKey;

    public OrchStepRunner(Id executionId, String stepKey) {
        this.executionId = executionId;
        this.stepKey = stepKey;
    }

    public void execute(QueueableContext qc) {

        Orch_Execution__c execRec = [
            SELECT Id, Status__c, StartedAt__c, EndedAt__c, MaxDurationSeconds__c
            FROM Orch_Execution__c WHERE Id = :executionId FOR UPDATE
        ];
        if (execRec.Status__c != 'Running') return;

        ExecutionGuards.assertNotTimedOut(execRec);

        Orch_StepExecution__c stepRec = [
            SELECT Id, Execution__c, StepKey__c, Status__c, Attempt__c, MaxAttempts__c,
                   InputJson__c, OutputJson__c, ErrorJson__c, NextRunAt__c,
                   RetryBackoffSeconds__c, IsRetryable__c, StartedAt__c, EndedAt__c,
                   CompensationStepKey__c, ParallelGroupKey__c
            FROM Orch_StepExecution__c
            WHERE Execution__c = :executionId AND StepKey__c = :stepKey
            LIMIT 1 FOR UPDATE
        ];

        if (stepRec.Status__c == 'Succeeded' || stepRec.Status__c == 'Skipped') return;

        // Enforce step idempotency
        String idemKey = 'step:' + String.valueOf(executionId) + ':' + stepKey + ':attempt:' + String.valueOf(stepRec.Attempt__c);
        IdempotencyService.IdemResult idem = IdempotencyService.begin('StepInvoke', idemKey, stepRec.InputJson__c, 60);

        if (idem.isDuplicate && !String.isBlank(idem.responseJson)) {
            // Reuse stored result
            stepRec.Status__c = 'Succeeded';
            stepRec.OutputJson__c = idem.responseJson;
            stepRec.EndedAt__c = System.now();
            update stepRec;
            OrchGraphService.enqueueNext(executionId, stepKey);
            return;
        }

        stepRec.Status__c = 'Running';
        stepRec.StartedAt__c = System.now();
        update stepRec;

        try {
            IOrchStep stepImpl = StepRegistry.resolve(stepKey);
            OrchStepContext ctx = new OrchStepContext();
            ctx.execRec = execRec;
            ctx.stepRec = stepRec;
            ctx.execState = OrchStateService.loadExecutionState(executionId);
            ctx.idempotencyKey = idemKey;

            OrchStepResult res = stepImpl.execute(ctx);

            stepRec.Status__c = 'Succeeded';
            stepRec.OutputJson__c = res.outputJson;
            stepRec.EndedAt__c = System.now();
            update stepRec;

            IdempotencyService.succeed(idem.record.Id, res.outputJson);

            OrchGraphService.enqueueNext(executionId, stepKey);

        } catch (OrchStepException ose) {
            handleFailure(execRec, stepRec, idem, ose.getMessage(), ose.retryable, ose.suggestedBackoffSeconds);
        } catch (Exception e) {
            // default: retryable depends on step configuration
            handleFailure(execRec, stepRec, idem, e.getMessage(), stepRec.IsRetryable__c, null);
        }
    }

    private static void handleFailure(
        Orch_Execution__c execRec,
        Orch_StepExecution__c stepRec,
        IdempotencyService.IdemResult idem,
        String message,
        Boolean retryable,
        Integer suggestedBackoffSeconds
    ) {
        Integer attempt = (stepRec.Attempt__c == null) ? 1 : Integer.valueOf(stepRec.Attempt__c) + 1;
        Integer maxA = (stepRec.MaxAttempts__c == null || stepRec.MaxAttempts__c <= 0) ? 3 : Integer.valueOf(stepRec.MaxAttempts__c);
        stepRec.Attempt__c = attempt;
        stepRec.ErrorJson__c = JSON.serialize(new Map<String,Object>{
            'message' => message,
            'retryable' => retryable,
            'attempt' => attempt,
            'maxAttempts' => maxA,
            'timestamp' => String.valueOf(System.now())
        });

        if (retryable == true && attempt <= maxA) {
            Integer backoff = (suggestedBackoffSeconds != null && suggestedBackoffSeconds > 0)
                ? suggestedBackoffSeconds
                : RetryPolicy.computeBackoffSeconds(attempt);

            stepRec.Status__c = 'RetryScheduled';
            stepRec.RetryBackoffSeconds__c = backoff;
            stepRec.NextRunAt__c = System.now().addSeconds(backoff);
            stepRec.EndedAt__c = System.now();
            update stepRec;

            IdempotencyService.fail(idem.record.Id, stepRec.ErrorJson__c);

            System.enqueueJob(new OrchRetryDelayRunner(stepRec.Id)); // see below
        } else {
            stepRec.Status__c = 'Failed';
            stepRec.EndedAt__c = System.now();
            update stepRec;

            IdempotencyService.fail(idem.record.Id, stepRec.ErrorJson__c);

            // Start saga compensation
            OrchSagaService.compensate(execRec.Id, stepRec.StepKey__c);
        }
    }
}

public class RetryPolicy {
    // exponential backoff with cap (enterprise safe)
    public static Integer computeBackoffSeconds(Integer attempt) {
        Integer base = 5;         // 5s
        Integer cap = 300;        // 5min
        Integer pow = (Integer)Math.pow(2, Math.min(attempt - 1, 6));
        Integer backoff = base * pow;
        return Math.min(backoff, cap);
    }
}
```

### 5.2 Delay runner (uses Scheduled Apex pattern safely)
Salesforce doesn’t support “sleep” in Apex. We schedule another Queueable at `NextRunAt__c`.

```apex
public with sharing class OrchRetryDelayRunner implements Queueable {
    private Id stepExecutionId;
    public OrchRetryDelayRunner(Id stepExecutionId){ this.stepExecutionId = stepExecutionId; }

    public void execute(QueueableContext qc){
        Orch_StepExecution__c s = [
            SELECT Id, Execution__c, StepKey__c, NextRunAt__c, Status__c
            FROM Orch_StepExecution__c WHERE Id = :stepExecutionId
        ];
        if (s.Status__c != 'RetryScheduled') return;

        if (s.NextRunAt__c != null && s.NextRunAt__c > System.now()) {
            // If not yet time, re-enqueue (small hop) – or use Scheduled Apex per org policy
            System.enqueueJob(new OrchRetryDelayRunner(stepExecutionId));
            return;
        }
        // Time reached: run step again
        System.enqueueJob(new OrchStepRunner(s.Execution__c, s.StepKey__c));
    }
}
```

> If your enterprise policy requires **true scheduled execution**, swap the re-enqueue loop with `System.schedule(...)` and store the scheduled job id on the step record.

