public class BranchEval {
    public static String chooseNext(List<Map<String,Object>> branches, Map<String,Object> state){
        for (Map<String,Object> b : branches) {
            String when = (String)b.get('when');
            if (when == 'default') return (String)b.get('next');
            if (evaluate(when, state)) return (String)b.get('next');
