### 6.3 Fan-out / fan-in enforcement
- Fan-out: enqueue `kpi_calc`, `fraud_check`, `limits_check`
- Fan-in: do not run `aggregate` until **all steps in group succeeded**

```apex
public with sharing class OrchGraphService {

    public static void enqueueNext(Id executionId, String completedStepKey) {
        // load template graph edges from cached template definition
        OrchTemplate tpl = OrchTemplateService.loadForExecution(executionId);

        // If completed step is part of a parallel group, check fan-in gate
        if (tpl.isParallelMember(completedStepKey)) {
            String groupKey = tpl.getParallelGroup(completedStepKey);
            if (!allGroupSucceeded(executionId, groupKey, tpl.getFanoutSteps(groupKey))) {
                return; // wait for others
            }
            // enqueue fan-in step
            System.enqueueJob(new OrchStepRunner(executionId, tpl.getFaninStep(groupKey)));
            return;
        }

        List<String> nextSteps = tpl.getNextSteps(completedStepKey);
        for (String nk : nextSteps) {
            if (tpl.isParallelStep(nk)) {
                // enqueue all fan-out steps
                for (String fan : tpl.getFanoutSteps(tpl.getParallelGroupKey(nk))) {
                    System.enqueueJob(new OrchStepRunner(executionId, fan));
                }
            } else if (tpl.isBranchStep(nk)) {
                // branch step decides the next
                System.enqueueJob(new OrchStepRunner(executionId, nk));
            } else {
                System.enqueueJob(new OrchStepRunner(executionId, nk));
            }
        }
    }

    private static Boolean allGroupSucceeded(Id executionId, String groupKey, List<String> members){
        Integer cnt = [
            SELECT count()
            FROM Orch_StepExecution__c
            WHERE Execution__c = :executionId
              AND ParallelGroupKey__c = :groupKey
              AND StepKey__c IN :members
              AND Status__c = 'Succeeded'
        ];
        return cnt == members.size();
    }
}
