## 7) Priority-2: Saga Compensation (enterprise)

On terminal failure, compensate succeeded steps in reverse order.

```apex
public with sharing class OrchSagaService {

    public static void compensate(Id executionId, String failedStepKey) {
        Orch_Execution__c execRec = [SELECT Id, Status__c FROM Orch_Execution__c WHERE Id=:executionId FOR UPDATE];
        execRec.Status__c = 'Compensating';
        update execRec;

        // all succeeded steps up to failure
        List<Orch_StepExecution__c> succeeded = [
            SELECT Id, StepKey__c, OutputJson__c, CompensationStepKey__c
            FROM Orch_StepExecution__c
            WHERE Execution__c = :executionId AND Status__c = 'Succeeded'
            ORDER BY StartedAt__c DESC
        ];

        for (Orch_StepExecution__c s : succeeded) {
            if (String.isBlank(s.CompensationStepKey__c)) continue;
            try {
                IOrchStep stepImpl = StepRegistry.resolve(s.StepKey__c);
                OrchStepContext ctx = new OrchStepContext();
                ctx.execRec = execRec;
                ctx.stepRec = s;
                ctx.execState = OrchStateService.loadExecutionState(executionId);
                stepImpl.compensate(ctx);

                s.Status__c = 'Compensated';
                update s;
            } catch (Exception e) {
                // enterprise choice: keep compensating best-effort, but log
                s.ErrorJson__c = JSON.serialize(new Map<String,Object>{'compensationError'=>e.getMessage()});
                update s;
            }
        }

        execRec.Status__c = 'Compensated';
        execRec.EndedAt__c = System.now();
        update execRec;
    }
}
```

