### 8.1 “Einstein step” implementation (Models API)
Salesforce’s Models API calls go through the **Einstein Trust Layer** citeturn2search24, so your step implementation is a governed callout.

**Step type:** `EinsteinModel` in template  
**Apex class:** `EinsteinModelStep`

```apex
public with sharing class EinsteinModelStep implements IOrchStep, Database.AllowsCallouts {

    public OrchStepResult execute(OrchStepContext ctx) {
        // Input: ctx.stepRec.InputJson__c must contain prompt + grounding data references
        Map<String,Object> payload = (Map<String,Object>)JSON.deserializeUntyped(ctx.stepRec.InputJson__c);

        String prompt = (String)payload.get('prompt');
        Map<String,Object> ground = (Map<String,Object>)payload.get('grounding'); // customer-360 grounded fields

        // Build your request for Models API (exact endpoint/shape depends on your enabled model)
        // NOTE: This is the exact "plug point": model invocation happens here, inside orchestrator step.
        HttpRequest req = new HttpRequest();
        req.setMethod('POST');
        req.setEndpoint(ModelsApiConfig.endpoint()); // e.g., Named Credential
        req.setHeader('Content-Type', 'application/json');

        Map<String,Object> reqBody = new Map<String,Object>{
            'input' => new Map<String,Object>{
                'prompt' => prompt,
                'grounding' => ground
            }
        };
        req.setBody(JSON.serialize(reqBody));

        Http h = new Http();
        HTTPResponse resp = h.send(req);

        if (resp.getStatusCode() >= 200 && resp.getStatusCode() < 300) {
            return OrchStepResult.ok(resp.getBody());
        }
        // retryable on 429/5xx, not retryable on 4xx (except 429)
        Boolean retryable = (resp.getStatusCode() == 429 || resp.getStatusCode() >= 500);
        Integer backoff = (resp.getStatusCode() == 429) ? 60 : 15;
        throw new OrchStepException('Einstein model call failed: ' + resp.getStatus(), retryable, backoff);
    }

    public void compensate(OrchStepContext ctx) {
        // usually no-op (unless model call triggers external side effects)
    }

    public Boolean defaultRetryable() { return true; }
}

public class ModelsApiConfig {
    public static String endpoint() {
        // Use Named Credential in enterprise (no hardcoded secrets)
        return 'callout:Einstein_Models_API/v1/generate';
    }
}
