```apex
public with sharing class OrchReplayService {

    public static void replayFrom(Id executionId, String stepKey) {
        Orch_Execution__c execRec = [SELECT Id, Status__c FROM Orch_Execution__c WHERE Id=:executionId FOR UPDATE];
        execRec.Status__c = 'Running';
        update execRec;

        OrchTemplate tpl = OrchTemplateService.loadForExecution(executionId);
        Set<String> downstream = tpl.downstreamSteps(stepKey);

        List<Orch_StepExecution__c> toReset = [
            SELECT Id, Status__c, OutputJson__c, ErrorJson__c, Attempt__c, NextRunAt__c
            FROM Orch_StepExecution__c
            WHERE Execution__c = :executionId AND StepKey__c IN :downstream
        ];
        for (Orch_StepExecution__c s : toReset) {
            s.Status__c = 'Queued';
            s.OutputJson__c = null;
            s.ErrorJson__c = null;
            s.Attempt__c = 0;
            s.NextRunAt__c = null;
        }
        update toReset;

        System.enqueueJob(new OrchStepRunner(executionId, stepKey));
    }
}
```

